WITH lines AS (SELECT id, plan, effective_from, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) e AS tier_value) SELECT DATE_TRUNC('MONTH', effective_from) AS activity_month, CASE WHEN tier_value >= 85 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_tier, MAX(tier_value) AS max_tier_value, SUM(CASE WHEN currency = 'THB' THEN tier_value ELSE 0 END) AS thb_tier_value, SIZE(COLLECT_SET(plan)) AS num_plans, AVG(tier_value) FILTER (WHERE currency = 'THB') AS thb_avg_tier_value FROM lines GROUP BY 1, 2 HAVING SIZE(COLLECT_SET(plan)) > 1 ORDER BY max_tier_value
